:divu.w eaw,reg9dn		is (op=8 & reg9dn & op68=3)... & eaw
{
	local denom = zext(eaw);
	local divis = reg9dn;
	local div = divis / denom;
	local rem = divis % denom;
	CF=0;
	resflags(div);
	reg9dn = (rem << 16) | (div & 0xffff);
	}

resflags_macro:
macro resflags(result) {
 NF = result s< 0;
 ZF = result == 0;
}
